/**
 * Configuration: environment + optional .env loading.
 *
 * No third-party dependency. The shell environment always wins;
 * .env only fills in values that are not already set.
 */

import { readFileSync } from "node:fs";

const _DEFAULTS = {
  CONTENT_HOARDER_DB: "data/app.db",
  CONTENT_HOARDER_NSFW_RULES: "nsfw_rules.json",
  CONTENT_HOARDER_HOST: "127.0.0.1",
  CONTENT_HOARDER_PORT: "8788",
  // Set to "1" to serve over HTTPS (requires cert.pem + key.pem in project root,
  // generated by mkcert). Default empty = plain HTTP.
  CONTENT_HOARDER_TLS: "",
  USER_AGENT: "content-hoarder/0.1 (local personal use)",
  // Reddit cookie transport: a real browser UA makes a logged-in session blend in, unlike
  // the generic USER_AGENT above (which still serves archives/youtube/karakeep). Override in
  // .env with YOUR actual browser's UA string for the closest blend. See docs/reddit-derisking.md.
  REDDIT_BROWSER_USER_AGENT:
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:140.0) Gecko/20100101 Firefox/140.0",
  // Reddit OAuth (installed-app; read + history + identity + save scopes). Client id is a PUBLIC
  // installed-app id (e.g. RedReader's) — there is no client secret. The redirect URI must match
  // that app's registered one (RedReader = redreader://rr_oauth_redir). Blank client id = cookie-only.
  REDDIT_OAUTH_CLIENT_ID: "",
  REDDIT_OAUTH_REDIRECT_URI: "redreader://rr_oauth_redir",
  KARAKEEP_BASE_URL: "",
  KARAKEEP_API_KEY: "",
  // PKMS promote bridge (spec 15): the capture endpoint + its token. Token may
  // come from PKMS .secrets/capture-token via env at runtime; never hardcoded.
  PKMS_CAPTURE_URL: "",
  PKMS_CAPTURE_TOKEN: "",
  LLM_BASE_URL: "http://127.0.0.1:1234/v1",
  LLM_MODEL: "",
} satisfies Record<string, string>;

/**
 * Load `KEY=VALUE` lines from a .env file into process.env.
 *
 * Existing environment variables are never overwritten. Lines that are blank,
 * comments (`#`), or lack `=` are ignored. Surrounding quotes are stripped.
 */
export function loadEnv(path?: string): void {
  const envPath = path ?? ".env";
  let content: string;

  try {
    // utf-8-sig-ish: strip a BOM so the first key still matches; errors
    // degrade a stray bad byte instead of crashing startup — the shell
    // environment is the authoritative source anyway.
    content = readFileSync(envPath, "utf8").replace(/^﻿/, "");
  } catch {
    return;
  }

  for (const raw of content.split("\n")) {
    const line = raw.trim();

    if (!line || line.startsWith("#") || !line.includes("=")) continue;
    const eq = line.indexOf("=");
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key && !(key in process.env)) {
      process.env[key] = value;
    }
  }
}

function hasDefault(key: string): key is keyof typeof _DEFAULTS {
  return Object.hasOwn(_DEFAULTS, key);
}

/** Return an env value, falling back to the built-in default ("" if unknown). */
export function get(key: string): string {
  const v = process.env[key];

  return v !== undefined ? v : hasDefault(key) ? _DEFAULTS[key] : "";
}

export function dbPath(): string {
  return get("CONTENT_HOARDER_DB");
}

export function host(): string {
  return get("CONTENT_HOARDER_HOST");
}

export function port(): number {
  const n = Number.parseInt(get("CONTENT_HOARDER_PORT"), 10);

  return Number.isNaN(n) ? 8788 : n;
}
